<script>
export default {
    name: 'Project2MobileView',
    data() {
        return {
            // Profile Images
            profileImages: [
                '/Project 2/profile.png'
            ],
            currentProfileIndex: 0,
            
            // Training Images
            trainingImages: [
                '/Project 2/training1.png',
                '/Project 2/training2.png'
            ],
            currentTrainingIndex: 0,
            
            // Challenge Images
            challengeImages: [
                '/Project 2/challenge1.png',
                '/Project 2/challenge2.png',
                '/Project 2/challenge3.png',
                '/Project 2/challengeInGame.png'
            ],
            currentChallengeIndex: 0,
            
            // Settings Images
            settingsImages: [
                '/Project 2/settings.png'
            ],
            currentSettingsIndex: 0
        }
    },
    computed: {
        currentProfileImage() {
            return this.profileImages[this.currentProfileIndex];
        },
        currentTrainingImage() {
            return this.trainingImages[this.currentTrainingIndex];
        },
        currentChallengeImage() {
            return this.challengeImages[this.currentChallengeIndex];
        },
        currentSettingsImage() {
            return this.settingsImages[this.currentSettingsIndex];
        }
    },
    mounted() {
        this.checkDesktopAndRedirect();
        this.addResizeListener();
    },
    beforeUnmount() {
        this.removeResizeListener();
    },
    methods: {
        // Profile Image Methods
        prevProfileImage() {
            this.currentProfileIndex = this.currentProfileIndex > 0 
                ? this.currentProfileIndex - 1 
                : this.profileImages.length - 1;
        },
        nextProfileImage() {
            this.currentProfileIndex = this.currentProfileIndex < this.profileImages.length - 1 
                ? this.currentProfileIndex + 1 
                : 0;
        },
        setProfileImage(index) {
            this.currentProfileIndex = index;
        },
        
        // Training Image Methods
        prevTrainingImage() {
            this.currentTrainingIndex = this.currentTrainingIndex > 0 
                ? this.currentTrainingIndex - 1 
                : this.trainingImages.length - 1;
        },
        nextTrainingImage() {
            this.currentTrainingIndex = this.currentTrainingIndex < this.trainingImages.length - 1 
                ? this.currentTrainingIndex + 1 
                : 0;
        },
        setTrainingImage(index) {
            this.currentTrainingIndex = index;
        },
        
        // Challenge Image Methods
        prevChallengeImage() {
            this.currentChallengeIndex = this.currentChallengeIndex > 0 
                ? this.currentChallengeIndex - 1 
                : this.challengeImages.length - 1;
        },
        nextChallengeImage() {
            this.currentChallengeIndex = this.currentChallengeIndex < this.challengeImages.length - 1 
                ? this.currentChallengeIndex + 1 
                : 0;
        },
        setChallengeImage(index) {
            this.currentChallengeIndex = index;
        },
        
        // Settings Image Methods
        prevSettingsImage() {
            this.currentSettingsIndex = this.currentSettingsIndex > 0 
                ? this.currentSettingsIndex - 1 
                : this.settingsImages.length - 1;
        },
        nextSettingsImage() {
            this.currentSettingsIndex = this.currentSettingsIndex < this.settingsImages.length - 1 
                ? this.currentSettingsIndex + 1 
                : 0;
        },
        setSettingsImage(index) {
            this.currentSettingsIndex = index;
        },
        
        // Desktop redirection methods
        checkDesktopAndRedirect() {
            const isDesktop = () => {
                const ua = navigator.userAgent;
                const hitUA = /Android|webOS|iPhone|iPod|iPad|BlackBerry|IEMobile|Opera Mini/i.test(ua);
                const hitSize = window.innerWidth < 768;
                const isDevToolsMobile = window.outerWidth !== window.innerWidth && window.innerWidth < 768;
                return !(hitUA || hitSize || isDevToolsMobile);
            };

            if (isDesktop()) {
                console.log('Desktop detected, redirecting to desktop view');
                this.$router.push({ name: 'Project2View' });
            }
        },
        addResizeListener() {
            this.resizeHandler = this.debounce(() => {
                this.checkDesktopAndRedirect();
            }, 300);
            window.addEventListener('resize', this.resizeHandler);
        },
        debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        },
        removeResizeListener() {
            if (this.resizeHandler) {
                window.removeEventListener('resize', this.resizeHandler);
            }
        }
    }
}
</script>

