<script>
export default {
    name: 'Project5MobileView',
    data() {
        return {
            // Control Videos
            controlVideos: [
                'http://xiangqianhuangstorage.zone.id/Project%205/Level2-controlTutorial1.mp4',
                'http://xiangqianhuangstorage.zone.id/Project%205/Level2-controlTutorial2.mp4'
            ],
            currentControlIndex: 0,
            
            // Driving Videos
            drivingVideos: [
                'http://xiangqianhuangstorage.zone.id/Project%205/level6-driving1.mp4',
                'http://xiangqianhuangstorage.zone.id/Project%205/level6-driving2.mp4'
            ],
            currentDrivingIndex: 0
        }
    },
    computed: {
        currentControlVideo() {
            return this.controlVideos[this.currentControlIndex];
        },
        currentDrivingVideo() {
            return this.drivingVideos[this.currentDrivingIndex];
        }
    },
    mounted() {
        // 确保页面从顶部开始
        window.scrollTo(0, 0);
        this.checkDesktopAndRedirect();
        this.addResizeListener();
    },
    beforeUnmount() {
        this.removeResizeListener();
    },
    methods: {
        // Control Video Methods
        prevControlVideo() {
            this.currentControlIndex = this.currentControlIndex > 0 
                ? this.currentControlIndex - 1 
                : this.controlVideos.length - 1;
        },
        nextControlVideo() {
            this.currentControlIndex = this.currentControlIndex < this.controlVideos.length - 1 
                ? this.currentControlIndex + 1 
                : 0;
        },
        setControlVideo(index) {
            this.currentControlIndex = index;
        },
        
        // Driving Video Methods
        prevDrivingVideo() {
            this.currentDrivingIndex = this.currentDrivingIndex > 0 
                ? this.currentDrivingIndex - 1 
                : this.drivingVideos.length - 1;
        },
        nextDrivingVideo() {
            this.currentDrivingIndex = this.currentDrivingIndex < this.drivingVideos.length - 1 
                ? this.currentDrivingIndex + 1 
                : 0;
        },
        setDrivingVideo(index) {
            this.currentDrivingIndex = index;
        },
        
        // Desktop redirection methods
        checkDesktopAndRedirect() {
            const isDesktop = () => {
                const ua = navigator.userAgent;
                const hitUA = /Android|webOS|iPhone|iPod|iPad|BlackBerry|IEMobile|Opera Mini/i.test(ua);
                const hitSize = window.innerWidth < 768;
                const isDevToolsMobile = window.outerWidth !== window.innerWidth && window.innerWidth < 768;
                return !(hitUA || hitSize || isDevToolsMobile);
            };

            if (isDesktop()) {
                console.log('Desktop detected, redirecting to desktop view');
                this.$router.push({ name: 'Project5View' });
            }
        },
        addResizeListener() {
            this.resizeHandler = this.debounce(() => {
                this.checkDesktopAndRedirect();
            }, 300);
            window.addEventListener('resize', this.resizeHandler);
        },
        debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        },
        removeResizeListener() {
            if (this.resizeHandler) {
                window.removeEventListener('resize', this.resizeHandler);
            }
        }
    }
}
</script>

