<script>
export default {
    name: 'Project9MobileView',
    data() {
        return {
            // Book Design Images
            bookDesignImages: [
                '/Project 9/bookDesign1.png',
                '/Project 9/bookDesign2.png'
            ],
            currentBookDesignIndex: 0,
            
            // Installation Images
            installationImages: [
                '/Project 9/installation1.png',
                '/Project 9/installation2.png',
                '/Project 9/installation3.png'
            ],
            currentInstallationIndex: 0
        }
    },
    computed: {
        currentBookDesignImage() {
            return this.bookDesignImages[this.currentBookDesignIndex];
        },
        currentInstallationImage() {
            return this.installationImages[this.currentInstallationIndex];
        }
    },
    mounted() {
        // 确保页面从顶部开始
        window.scrollTo(0, 0);
        this.checkDesktopAndRedirect();
        this.addResizeListener();
    },
    beforeUnmount() {
        this.removeResizeListener();
    },
    methods: {
        // Book Design Image Methods
        prevBookDesignImage() {
            this.currentBookDesignIndex = this.currentBookDesignIndex > 0 
                ? this.currentBookDesignIndex - 1 
                : this.bookDesignImages.length - 1;
        },
        nextBookDesignImage() {
            this.currentBookDesignIndex = this.currentBookDesignIndex < this.bookDesignImages.length - 1 
                ? this.currentBookDesignIndex + 1 
                : 0;
        },
        setBookDesignImage(index) {
            this.currentBookDesignIndex = index;
        },
        
        // Installation Image Methods
        prevInstallationImage() {
            this.currentInstallationIndex = this.currentInstallationIndex > 0 
                ? this.currentInstallationIndex - 1 
                : this.installationImages.length - 1;
        },
        nextInstallationImage() {
            this.currentInstallationIndex = this.currentInstallationIndex < this.installationImages.length - 1 
                ? this.currentInstallationIndex + 1 
                : 0;
        },
        setInstallationImage(index) {
            this.currentInstallationIndex = index;
        },
        
        // Desktop redirection methods
        checkDesktopAndRedirect() {
            const isDesktop = () => {
                const ua = navigator.userAgent;
                const hitUA = /Android|webOS|iPhone|iPod|iPad|BlackBerry|IEMobile|Opera Mini/i.test(ua);
                const hitSize = window.innerWidth < 768;
                const isDevToolsMobile = window.outerWidth !== window.innerWidth && window.innerWidth < 768;
                return !(hitUA || hitSize || isDevToolsMobile);
            };

            if (isDesktop()) {
                console.log('Desktop detected, redirecting to desktop view');
                this.$router.push({ name: 'Project9View' });
            }
        },
        addResizeListener() {
            this.resizeHandler = this.debounce(() => {
                this.checkDesktopAndRedirect();
            }, 300);
            window.addEventListener('resize', this.resizeHandler);
        },
        debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        },
        removeResizeListener() {
            if (this.resizeHandler) {
                window.removeEventListener('resize', this.resizeHandler);
            }
        }
    }
}
</script>

