<script>
export default {
    name: 'Project1MobileView',
    data() {
        return {
            // Exhibition Images
            exhibitionImages: [
                '/Project 1/vk1.png',
                '/Project 1/vk2.png',
                '/Project 1/vk3.png',
                '/Project 1/vk4.png'
            ],
            currentExhibitionIndex: 0,
            
            // Overview Images
            overviewImages: [
                '/Project 1/overview.png'
            ],
            currentOverviewIndex: 0,
            
            // Interaction Videos
            interactionVideos: [
                'http://xiangqianhuangstorage.zone.id/Project%201/observe.mp4',
                'http://xiangqianhuangstorage.zone.id/Project%201/toggle.mp4',
                'http://xiangqianhuangstorage.zone.id/Project%201/upload.mp4',
                'http://xiangqianhuangstorage.zone.id/Project%201/timeline.mp4'
            ],
            currentInteractionIndex: 0,
            
            // Document Images
            documentImages: [
                '/Project 1/technicalDocument.png'
            ],
            currentDocumentIndex: 0
        }
    },
    computed: {
        currentExhibitionImage() {
            return this.exhibitionImages[this.currentExhibitionIndex];
        },
        currentOverviewImage() {
            return this.overviewImages[this.currentOverviewIndex];
        },
        currentInteractionVideo() {
            return this.interactionVideos[this.currentInteractionIndex];
        },
        currentDocumentImage() {
            return this.documentImages[this.currentDocumentIndex];
        }
    },
    mounted() {
        this.checkDesktopAndRedirect();
        this.addResizeListener();
    },
    beforeUnmount() {
        this.removeResizeListener();
    },
    methods: {
        // Exhibition Image Methods
        prevExhibitionImage() {
            this.currentExhibitionIndex = this.currentExhibitionIndex > 0 
                ? this.currentExhibitionIndex - 1 
                : this.exhibitionImages.length - 1;
        },
        nextExhibitionImage() {
            this.currentExhibitionIndex = this.currentExhibitionIndex < this.exhibitionImages.length - 1 
                ? this.currentExhibitionIndex + 1 
                : 0;
        },
        setExhibitionImage(index) {
            this.currentExhibitionIndex = index;
        },
        
        // Overview Image Methods
        prevOverviewImage() {
            this.currentOverviewIndex = this.currentOverviewIndex > 0 
                ? this.currentOverviewIndex - 1 
                : this.overviewImages.length - 1;
        },
        nextOverviewImage() {
            this.currentOverviewIndex = this.currentOverviewIndex < this.overviewImages.length - 1 
                ? this.currentOverviewIndex + 1 
                : 0;
        },
        setOverviewImage(index) {
            this.currentOverviewIndex = index;
        },
        
        // Interaction Video Methods
        prevInteractionVideo() {
            this.currentInteractionIndex = this.currentInteractionIndex > 0 
                ? this.currentInteractionIndex - 1 
                : this.interactionVideos.length - 1;
        },
        nextInteractionVideo() {
            this.currentInteractionIndex = this.currentInteractionIndex < this.interactionVideos.length - 1 
                ? this.currentInteractionIndex + 1 
                : 0;
        },
        setInteractionVideo(index) {
            this.currentInteractionIndex = index;
        },
        onInteractionVideoEnded() {
            this.nextInteractionVideo();
        },
        
        // Document Image Methods
        prevDocumentImage() {
            this.currentDocumentIndex = this.currentDocumentIndex > 0 
                ? this.currentDocumentIndex - 1 
                : this.documentImages.length - 1;
        },
        nextDocumentImage() {
            this.currentDocumentIndex = this.currentDocumentIndex < this.documentImages.length - 1 
                ? this.currentDocumentIndex + 1 
                : 0;
        },
        setDocumentImage(index) {
            this.currentDocumentIndex = index;
        },
        
        // Desktop redirection methods
        checkDesktopAndRedirect() {
            const isDesktop = () => {
                const ua = navigator.userAgent;
                const hitUA = /Android|webOS|iPhone|iPod|iPad|BlackBerry|IEMobile|Opera Mini/i.test(ua);
                const hitSize = window.innerWidth < 768;
                const isDevToolsMobile = window.outerWidth !== window.innerWidth && window.innerWidth < 768;
                return !(hitUA || hitSize || isDevToolsMobile);
            };

            if (isDesktop()) {
                console.log('Desktop detected, redirecting to desktop view');
                this.$router.push({ name: 'Project1View' });
            }
        },
        addResizeListener() {
            this.resizeHandler = this.debounce(() => {
                this.checkDesktopAndRedirect();
            }, 300);
            window.addEventListener('resize', this.resizeHandler);
        },
        debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        },
        removeResizeListener() {
            if (this.resizeHandler) {
                window.removeEventListener('resize', this.resizeHandler);
            }
        }
    }
}
</script>

